import{z as s,x as l,o,c as p,q as t,j as A,D as E,d as a,s as B,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Arrow–Debreu 或有商品","description":"","frontmatter":{"title":"Arrow–Debreu 或有商品","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/arrow-debreu-paper.md","filePath":"econ/arrow-debreu-paper.md","lastUpdated":1791413859000}'),d={name:"econ/arrow-debreu-paper.md"};function m(u,e,c,D,h,w){const n=l("Mermaid");return o(),p("div",null,[e[2]||(e[2]=t('<h1 id="arrow–debreu-或有商品" tabindex="-1">Arrow–Debreu 或有商品 <a class="header-anchor" href="#arrow–debreu-或有商品" aria-label="Permalink to &quot;Arrow–Debreu 或有商品&quot;">​</a></h1><div class="epigraph"><p>把商品按发生的状态来标记，不确定下的配置就回到确定环境里的竞争均衡。</p><footer>—— Arrow, The Role of Securities in the Optimal Allocation of Risk-Bearing, Review of Economic Studies 1964（1953 年法语稿）</footer></div><p>附录对照，不插入主干；本篇开「经典论文对照」这门附录课，读法是拿原文对照主干已经用过的装置，不是从零起手，也不接在某一主干课之后。主干已在<a href="/econ/state-contingent">状态依存</a>、<a href="/econ/walrasian-equilibrium">瓦尔拉斯均衡</a>、<a href="/econ/ge-existence">存在性</a>里用过或有商品与不动点；这里对照 <strong>Arrow 1953/1964 原文的问题</strong>：完整的或有商品市场太重，能否改成一套证券，仍实施最优风险分担。不重做角谷不动点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Debreu 式的商品可以带日期、地点与状态：一单位「下雨时的小麦」与「晴天的小麦」是不同商品。若每种状态–商品都有现货市场在 \\(t=0\\) 开齐，不确定只是把商品空间加维，<a href="/econ/welfare-theorems">第一福利定理</a>原样适用。Arrow 问的缺口是实施：真实经济没有为每个状态开一个小麦市场。有没有一种更瘦的证券结构，使人们先对状态下注，再在该状态的现货市场上买小麦？</p><p>1953 年法语文本针对的是风险分担，不是存在性。Arrow–Debreu（1954, <em>Econometrica</em>）那篇存在性论文是另一份对照，主干<a href="/econ/ge-existence">存在性</a>已经取过不动点骨架。本附录只钉或有商品与证券的等价。</p><p><span class="marginnote">Arrow 证券：在指定状态支付一单位计价物、其余状态支付零。有限状态、每种状态一张，再加上各状态的现货市场，即可复制完整或有商品配置。</span></p><p><span class="marginnote">数字实例：假设只有「旱」「涝」两个状态。与其分别为「旱田小麦」「涝田小麦」开两个市场，只需各买一张对应状态的 Arrow 证券——今天各付一点钱，指定状态实现时付 1 元，拿去现货市场买小麦。市场数目从「状态 × 商品」降到「状态数」，这就是降维。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两阶段。\\(t=0\\) 只交易 Arrow 证券（或能张成同样支付的普通证券）。状态 \\(s\\) 实现后，证券结算，代理人带着计价物进入 \\(s\\) 的现货市场，按 \\(s\\) 的现货价格购买商品。若证券张成所有状态，预算的状态依存与或有商品经济相同，均衡配置一致。证券不必以小麦计价；用计价物标记状态即可。</p>',10)),(o(),A(i,null,{default:E(()=>[B(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CC%5B%22%E6%88%96%E6%9C%89%E5%95%86%E5%93%81%3A%20%E6%AF%8F%E4%B8%AA%E7%8A%B6%E6%80%81%E4%B8%80%E7%A7%8D%E5%B0%8F%E9%BA%A6%22%5D%20--%3E%20AD%5B%22t%3D0%20%E4%B8%80%E6%AC%A1%E4%B9%B0%E9%BD%90%22%5D%0A%20%20AR%5B%22Arrow%20%E8%AF%81%E5%88%B8%E5%BC%A0%E6%88%90%E7%8A%B6%E6%80%81%22%5D%20--%3E%20SPOT%5B%22%E7%8A%B6%E6%80%81%20s%20%E7%9A%84%E7%8E%B0%E8%B4%A7%E5%B8%82%E5%9C%BA%22%5D%0A%20%20SPOT%20--%3E%20EQ%5B%22%E5%90%8C%E4%B8%80%E9%A3%8E%E9%99%A9%E5%88%86%E6%8B%85%22%5D%0A%20%20AD%20--%3E%20EQ%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("p",null,[a("不完全市场是后话：证券张不成全部状态时，配置一般达不到或有商品帕累托集。原文的贡献是完全市场下的"),r("strong",null,"降维"),a("，不是证明现实市场完全。")],-1)),e[4]||(e[4]=r("h2",{id:"机制",tabindex:"-1"},[a("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=r("p",null,"机制是把「哪一种小麦」拆成「哪一个状态的购买力」乘「该状态的现货」。状态价格（证券价格）承担风险分担；现货价格承担该状态下的相对稀缺。主干 SDF 课里的 \\(m(s)\\propto\\) 状态价格 / 概率，就是这套证券价格的随机折现写法。本附录不把 \\(m\\) 再推一遍，只对照：Arrow 的证券是 \\(m\\) 的可交易实现。",-1)),e[6]||(e[6]=r("p",null,"第一张图并列两条路线；这一张按时间拆开「复制的机制」：一张 Arrow 证券加上现货购买，如何在状态实现前后接力，交付原本要单独开市的「下雨时的小麦」。",-1)),(o(),A(i,null,{default:E(()=>[B(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20WANT%5B%22%E6%83%B3%E8%A6%81%EF%BC%9A%E3%80%8C%E4%B8%8B%E9%9B%A8%E6%97%B6%E7%9A%84%E4%B8%80%E5%8D%95%E4%BD%8D%E5%B0%8F%E9%BA%A6%E3%80%8D%22%5D%20--%3E%20BUY%5B%22t%3D0%EF%BC%9A%E4%B9%B0%E5%85%A5%E8%B6%B3%E5%A4%9F%E5%A4%9A%E5%BC%A0%E3%80%8E%E4%B8%8B%E9%9B%A8%E7%8A%B6%E6%80%81%E3%80%8FArrow%20%E8%AF%81%E5%88%B8%22%5D%0A%20%20BUY%20--%3E%20HIT%5B%22%E4%B8%8B%E9%9B%A8%E5%AE%9E%E7%8E%B0%EF%BC%9A%E6%AF%8F%E5%BC%A0%E8%AF%81%E5%88%B8%E4%BB%98%E5%87%BA%E4%B8%80%E5%85%83%E8%AE%A1%E4%BB%B7%E7%89%A9%22%5D%0A%20%20BUY%20--%3E%20MISS%5B%22%E4%B8%8D%E4%B8%8B%E9%9B%A8%EF%BC%9A%E8%AF%81%E5%88%B8%E4%BB%98%E9%9B%B6%EF%BC%8C%E8%87%AA%E5%8A%A8%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20HIT%20--%3E%20SPOT%5B%22%E8%BF%9B%E5%85%A5%E4%B8%8B%E9%9B%A8%E7%8A%B6%E6%80%81%E7%9A%84%E7%8E%B0%E8%B4%A7%E5%B8%82%E5%9C%BA%EF%BC%8C%E7%94%A8%E8%AE%A1%E4%BB%B7%E7%89%A9%E4%B9%B0%E5%B0%8F%E9%BA%A6%22%5D%0A%20%20SPOT%20--%3E%20DONE%5B%22%E7%AD%89%E4%BB%B7%E4%BA%8E%E6%8C%81%E6%9C%89%E4%B8%80%E5%8D%95%E4%BD%8D%E7%9A%84%E6%88%96%E6%9C%89%E5%95%86%E5%93%81%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=t('<h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干<a href="/econ/state-contingent">状态依存</a>已经用加标商品讲过风险分担；<a href="/econ/ge-existence">存在性</a>已经用不动点。<a href="/econ/why-intermediaries">中介</a>则从「市场不全」起笔，正因为这篇世界里银行没有位置。把 1954/1953 插进中介课之前，会让读者以为银行是一般均衡的一章。附录只对照原文如何把不确定性收成维数，以及证券如何实施或有商品。</p><p><span class="marginnote">Arrow and Debreu, <em>Econometrica</em> 22(3), 1954。Arrow 证券文常引 1964 年 <em>RES</em> 英译本（法文 1953）。不要给两篇发明 arXiv 号。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1954 存在性论文与 1953/1964 证券论文读成同一篇。前者回答「竞争均衡有没有」，后者回答「不确定能否用证券实施」。也不要在附录里开不完全市场一般均衡（GEI）的存在性——那是 Magill–Quinzii 一线，主干未收。</p><p>下一篇附录对照 Debreu《价值理论》如何把商品、价格与存在性写成公理系统。</p><p>不完全市场、太阳黑子、无限维，都是后继，不是 1954 年未写完的章节。本附录也不重画埃奇沃思盒——那是主干配置课的教具。</p><p>1954 年短文的重点是存在性，或有商品是把不确定性塞进有限维的方法。Arrow 证券文（1953/1964）才把风险分担的实施单独写出。</p><p><span class="marginnote">术语翻译：「状态价格」是今天为「指定状态到手一元钱」支付的保费。坏状态的状态价格相对更贵——那时的钱最值钱；把它除以该状态的概率，得到的正是 SDF 课里的 \\(m(s)\\)。风险分担的英语叫 risk-sharing，说的就是大家分摊这些保费的组合。</span></p><p>完整市场使<a href="/econ/why-intermediaries">中介</a>没有位置。读这篇是为了看银行课为何必须从市场不全起笔。</p><p>不动点不是算法，也不给出唯一性。主干存在性课已用 Kakutani；这里只对照原文把状态写成坐标。</p><p><span class="marginnote">常见误区：以为 Arrow–Debreu 声称「现实市场是完备的」。原文做的是理论降维——只要证券张成全部状态，最优配置就能用证券加现货实施；现实中张不成，才轮到不完全市场研究、也才轮到中介与银行登场。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Arrow 1953/1964：或有商品可用 Arrow 证券加现货复制。</li><li>完全张成时风险分担回到确定环境的福利定理。</li><li>1954 存在性是另一篇，见主干存在性课。</li><li>出处：Arrow, <em>RES</em> 1964；对照 Arrow and Debreu, <em>Econometrica</em> 1954。</li></ul>',14))])}const C=s(d,[["render",m]]);export{b as __pageData,C as default};
